      uiRules: "Règles et règlements",
      uiAgree: "J'accepte",
      uiRulesLogged: "Accepté 07:41 · enregistré sur le check-in",
      descWait: "Vous devez attendre 20 minutes",
      descOffice: "Veuillez vous présenter au bureau",
      descParking: "Allez au parking : [P1] 04",
      descCustom: "Appelez votre répartiteur pour qu'il mette à jour la réservation",
      actRamp: "Affecter à un quai",
